INSERT INTO public.exercise_lottie_animations (
    exercise_id,
    figure_variant,
    lottie_json,
    storage_url
)
SELECT
    exercise.id,
    animation_records.figure_variant,
    animation_records.lottie_json,
    animation_records.storage_url
FROM animation_records
JOIN public.exercises AS exercise
    ON exercise.name_en = animation_records.name_en
ON CONFLICT (exercise_id, figure_variant) DO UPDATE
SET
    lottie_json = EXCLUDED.lottie_json,
    storage_url = EXCLUDED.storage_url,
    updated_at = now();

WITH updated_assets(name_en, slug) AS (
    VALUES
        ('Ab Roller', 'ab-roller'),
        ('Ankle On The Knee', 'ankle-on-the-knee'),
        ('Anterior Tibialis-SMR', 'anterior-tibialis-smr'),
        ('Axle Deadlift', 'axle-deadlift'),
        ('World''s Greatest Stretch', 'worlds-greatest-stretch')
)
UPDATE public.exercises AS exercise
SET
    animation_url = concat('https://nsrhhvwytusltnikqplk.supabase.co/storage/v1/object/public/exercises/animations/workout-test/v3/', updated_assets.slug, '-man.json'),
    animation_url_male = concat('https://nsrhhvwytusltnikqplk.supabase.co/storage/v1/object/public/exercises/animations/workout-test/v3/', updated_assets.slug, '-man.json'),
    animation_url_female = concat('https://nsrhhvwytusltnikqplk.supabase.co/storage/v1/object/public/exercises/animations/workout-test/v3/', updated_assets.slug, '-woman.json')
FROM updated_assets
WHERE exercise.name_en = updated_assets.name_en;
